contract:
{
  "interface": {
    "mode": "stdin_stdout",
    "signature": "stdin -> stdout",
    "input_channel": "stdin",
    "output_channel": "stdout"
  },
  "preconditions": [
    {
      "id": "P1",
      "expression": "1 <= t <= 100000",
      "description": "The number of test cases t is between 1 and 100,000."
    },
    {
      "id": "P2",
      "expression": "all(1 <= n <= m <= 1000000 for n, m in test_cases)",
      "description": "For each test case, the number of residents n and the number of friendship pairs m are between 1 and 1,000,000, and n is less than or equal to m."
    },
    {
      "id": "P3",
      "expression": "all(1 <= a_i <= n and 1 <= b_i <= n for n, m, pairs in test_cases for a_i, b_i in pairs)",
      "description": "For each friendship pair (a_i, b_i) in each test case, both a_i and b_i are between 1 and n."
    },
    {
      "id": "P4",
      "expression": "all(len(pairs) == m for n, m, pairs in test_cases)",
      "description": "The number of friendship pairs m matches the number of provided pairs for each test case."
    },
    {
      "id": "P5",
      "expression": "all(any(a_i == i for a_i, b_i in pairs) for n, m, pairs in test_cases for i in range(1, n+1))",
      "description": "Each resident i is acquainted with their own cat i in each test case."
    },
    {
      "id": "P6",
      "expression": "all(len(set(pairs)) == m for n, m, pairs in test_cases)",
      "description": "Each friendship pair (a_i, b_i) is unique in each test case."
    },
    {
      "id": "P7",
      "expression": "sum(n for n, m, pairs in test_cases) <= 1000000",
      "description": "The sum of n over all test cases is at most 1,000,000."
    },
    {
      "id": "P8",
      "expression": "sum(m for n, m, pairs in test_cases) <= 1000000",
      "description": "The sum of m over all test cases is at most 1,000,000."
    }
  ],
  "postconditions": [
    {
      "id": "Q1",
      "expression": "return_value in ['No', 'Yes']",
      "description": "The output is either 'No' or 'Yes'."
    },
    {
      "id": "Q2",
      "expression": "return_value == 'No' or (len(jury) + len(contestants) == n and jury and contestants)",
      "description": "If the output is 'Yes', the sum of the number of jury members and contestants is n, and both groups are non-empty."
    },
    {
      "id": "Q3",
      "expression": "return_value == 'No' or len(set(jury)) == len(jury)",
      "description": "If the output is 'Yes', the jury members are distinct."
    },
    {
      "id": "Q4",
      "expression": "return_value == 'No' or len(set(contestants)) == len(contestants)",
      "description": "If the output is 'Yes', the contestants are distinct."
    },
    {
      "id": "Q5",
      "expression": "return_value == 'No' or all(1 <= j <= n for j in jury)",
      "description": "If the output is 'Yes', each jury member is a valid resident index."
    },
    {
      "id": "Q6",
      "expression": "return_value == 'No' or all(1 <= c <= n for c in contestants)",
      "description": "If the output is 'Yes', each contestant is a valid cat index."
    },
    {
      "id": "Q7",
      "expression": "return_value == 'No' or all(j not in [b_i for a_i, b_i in pairs if b_i in contestants] for j in jury)",
      "description": "If the output is 'Yes', no jury member is acquainted with any contestant."
    }
  ],
  "
